package io.github.jesterportfolio.hearth.survival.rpg;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.io.*;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;
import io.github.jesterportfolio.hearth.survival.platform.PlatformIo;
/** Durable preimage and cleanup intent. Worker only receives immutable serialized bytes. */
public final class DeathJournal implements AutoCloseable {
 private final Path directory;private final UUID group;private final PlatformIo files=new PlatformIo();private final Set<UUID> held=ConcurrentHashMap.newKeySet();private volatile boolean ready;
 public DeathJournal(Path data,UUID group){this.group=group;directory=data.resolve("rpg-death-pending");}
 private Path path(UUID player,String suffix){return directory.resolve(player+suffix);}
 public CompletionStage<Void> open(){return files.submit(()->{if(!directory.getParent().equals(directory.getParent().toRealPath()))throw new IOException("DEATH_PATH");if(!Files.exists(directory,LinkOption.NOFOLLOW_LINKS))Files.createDirectory(directory);if(!directory.equals(directory.toRealPath()))throw new IOException("DEATH_PATH");var ids=new HashSet<UUID>();try(var paths=Files.list(directory)){var list=paths.limit(30001).toList();if(list.size()>30000)throw new IOException("DEATH_MARKER_LIMIT");for(var p:list){String name=p.getFileName().toString();if(!name.matches("[a-f0-9-]{36}\\.(before|pending|done)")||!p.equals(p.toRealPath())||!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.size(p)>(name.endsWith(".before")?4194304:1024))throw new IOException("DEATH_MARKER");ids.add(UUID.fromString(name.substring(0,36)));if(ids.size()>10000)throw new IOException("DEATH_MARKER_LIMIT");}}for(var id:ids){if(Files.exists(path(id,".done"))){validate(path(id,".done"));if(Files.exists(path(id,".pending"))&&!Files.isSameFile(path(id,".pending"),path(id,".done"))){held.add(id);continue;}finishCleanup(id);}else{if(Files.exists(path(id,".pending")))validate(path(id,".pending"));held.add(id);}}ready=true;return (Void)null;});}
 private void validate(Path p)throws Exception{var lines=Files.readAllLines(p);if(lines.size()!=5||!lines.get(0).equals("Hearth death inventory v1")||!lines.get(1).equals(group.toString())||!lines.get(2).matches("[a-f0-9]{64}")||!lines.get(3).matches("[a-f0-9]{64}"))throw new IOException("DEATH_MARKER");UUID.fromString(lines.get(4));}
 public boolean held(UUID player){return !ready||held.contains(player);}public Set<UUID> heldPlayers(){return Set.copyOf(held);}
 public CompletionStage<Ticket> acquire(UUID player,String before,String after,byte[] original){if(!ready||!before.matches("[a-f0-9]{64}")||!after.matches("[a-f0-9]{64}")||original.length>4194304||!held.add(player))return CompletableFuture.failedFuture(new IllegalStateException("DEATH_HELD"));byte[] frozen=original.clone();return files.submit(()->{Path payload=path(player,".before");Files.createFile(payload,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));try(var out=Files.newOutputStream(payload,StandardOpenOption.WRITE)){out.write(frozen);}force(payload);var lease=RuntimeLease.acquire(path(player,".pending"),"Hearth death inventory v1\n"+group+"\n"+before+"\n"+after+"\n").orElseThrow();syncDirectory();return new Ticket(player,lease);});}
 public static byte[] encode(org.bukkit.inventory.ItemStack[] original)throws Exception{var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){out.writeInt(1);out.writeInt(original.length);for(var item:original){byte[] data=item==null||item.isEmpty()?new byte[0]:item.serializeAsBytes();out.writeInt(data.length);out.write(data);if(bytes.size()>4194304)throw new IOException("DEATH_BEFORE_LIMIT");}}return bytes.toByteArray();}
 public final class Ticket{private final UUID player;private final RuntimeLease.Lease lease;private Ticket(UUID player,RuntimeLease.Lease lease){this.player=player;this.lease=lease;}public CompletionStage<Void> clean(){return files.submit(()->{lease.retire(path(player,".done"));syncDirectory();finishCleanup(player);held.remove(player);return (Void)null;});}}
 private void finishCleanup(UUID id)throws Exception{Files.deleteIfExists(path(id,".pending"));Files.deleteIfExists(path(id,".before"));syncDirectory();Files.delete(path(id,".done"));syncDirectory();}
 private void syncDirectory()throws Exception{try(var c=java.nio.channels.FileChannel.open(directory,StandardOpenOption.READ)){c.force(true);}}
 private static void force(Path path)throws Exception{try(var c=java.nio.channels.FileChannel.open(path,StandardOpenOption.WRITE)){c.force(true);}}
 public CompletionStage<Void> drain(){return files.submit(()->null);}public void close(){files.close();}
}
